from typing import List

class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # Dictionary to store count of each number across all subarrays of size k
        count = {}

        # Slide window over the array
        for i in range(n - k + 1):
            window = nums[i:i+k]
            for num in window:
                count[num] = count.get(num, 0) + 1

        # Collect all numbers that appear exactly once
        almost_missing = [num for num, c in count.items() if c == 1]

        return max(almost_missing) if almost_missing else -1
